mapper.select:
SELECT A.PORTFOLIO_ID portfolioId, C.PORTFOLIO_NAME portfolioName, A.IND_ID indId, B.IND_NAME indName, B.IND_TYPE indType, B.SUP_TYPE supType, B.WARN_COND warnCond, B.FOUL_COND foulCond, B.APPROVE_COND approveCond, B.IS_ENABLED isEnabled, A.PORTFOLIO_LEVEL portfolioLevel, A.START_DATE startDate, A.END_DATE endDate FROM RSK_PORTFOLIO_INDICATOR A LEFT JOIN RSK_ISUP_INDICATOR B on A.IND_ID=B.IND_ID LEFT JOIN PTL_PORTFOLIO C ON A.PORTFOLIO_ID=C.PORTFOLIO_ID
A.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND B.IND_NAME LIKE CONCAT(CONCAT('%',#{indName}),'%')
AND A.PORTFOLIO_LEVEL = #{portfolioLevel,jdbcType=VARCHAR}
AND B.SUP_TYPE = #{supType,jdbcType=VARCHAR}

SELECT A.PORTFOLIO_ID portfolioId, C.PTL_BAG_NAME portfolioName, A.IND_ID indId, B.IND_NAME indName, B.IND_TYPE indType, B.SUP_TYPE supType, B.WARN_COND warnCond, B.FOUL_COND foulCond, B.APPROVE_COND approveCond, B.IS_ENABLED isEnabled, A.PORTFOLIO_LEVEL portfolioLevel, A.START_DATE startDate, A.END_DATE endDate FROM RSK_PORTFOLIO_INDICATOR A LEFT JOIN RSK_ISUP_INDICATOR B on A.IND_ID=B.IND_ID LEFT JOIN RSK_PORTFOLIO_PACKAGE C on A.PORTFOLIO_ID=C.PTL_BAG_ID
A.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND B.IND_NAME LIKE CONCAT(CONCAT('%',#{indName}),'%')
AND A.PORTFOLIO_LEVEL = #{portfolioLevel,jdbcType=VARCHAR}
AND B.SUP_TYPE = #{supType,jdbcType=VARCHAR}

select X.PORTFOLIO_ID portfolioId, X.IND_ID indId, X.IND_NAME indName, X.PORTFOLIO_LEVEL portfolioLevel, X.portfolioName, X.START_DATE startDate, X.END_DATE endDate, X.IND_TYPE indType, X.SUP_TYPE supType, X.WARN_COND warnCond, X.FOUL_COND foulCond, X.APPROVE_COND approveCond, X.IS_ENABLED isEnabled from ( SELECT A.PORTFOLIO_ID , A.IND_ID , B.IND_NAME, A.PORTFOLIO_LEVEL , case when A.PORTFOLIO_LEVEL='02' then (select PTL_BAG_NAME from RSK_PORTFOLIO_PACKAGE where PTL_BAG_ID=A.PORTFOLIO_ID) else C.PORTFOLIO_NAME end portfolioName, A.START_DATE , A.END_DATE , B.IND_TYPE , B.SUP_TYPE , B.WARN_COND , B.FOUL_COND , B.APPROVE_COND , B.IS_ENABLED FROM RSK_PORTFOLIO_INDICATOR A LEFT JOIN RSK_ISUP_INDICATOR B on A.IND_ID=B.IND_ID LEFT JOIN PTL_PORTFOLIO C ON A.PORTFOLIO_ID=C.PORTFOLIO_ID
A.IND_ID = #{indId,jdbcType=VARCHAR}
AND PORTFOLIO_LEVEL = #{portfolioLevel,jdbcType=VARCHAR}
AND (A.PORTFOLIO_LEVEL = '02' OR (A.PORTFOLIO_LEVEL = '01' AND C.MDATE > #{platDate,jdbcType=DATE} ))
) X
portfolioName LIKE CONCAT(CONCAT('%',#{portfolioName}),'%')

 	select IND_ID id,IND_NAME name,IND_TYPE as pId       
	from RSK_ISUP_INDICATOR 


		IND_TYPE = #{indType}
